SELECT 
FROM CAM_RU_PROCESS_DEFINITION
WHERE partition_id = #{partitionId} AND process_definition_key = #{key}

SELECT 
FROM CAM_RU_PROCESS_DEFINITION
WHERE partition_id = #{partitionId} AND tenant_id = #{tenantId}
  AND bpmn_process_id = #{bpmnProcessId} AND version = #{version}
ORDER BY process_definition_key

SELECT 
FROM CAM_RU_PROCESS_DEFINITION
WHERE partition_id = #{partitionId} AND process_definition_key > #{afterKey}
ORDER BY process_definition_key
LIMIT #{limit}

mapper.update:
UPDATE CAM_RU_PROCESS_DEFINITION
SET tenant_id = #{row.tenantId}, bpmn_process_id = #{row.bpmnProcessId},
  version = #{row.version}, version_tag = #{row.versionTag,jdbcType=VARCHAR},
  deployment_key = #{row.deploymentKey}, resource_name = #{row.resourceName},
  state = #{row.state}, payload = #{row.payload}
WHERE partition_id = #{partitionId} AND process_definition_key = #{row.processDefinitionKey}

